INSERT INTO work_queue (id,task_type,payload,status,created_at) SELECT 'pending-backfill-guard','metadata','{}','guard_failed',unixepoch() WHERE NOT ((SELECT COUNT(*) FROM c JOIN song_masters sm ON sm.id=c.master_id AND sm.album_id='pending-uploads' AND sm.title IS c.title_snapshot AND sm.disc IS c.disc_snapshot AND sm.track IS c.track_snapshot JOIN song_instances si ON si.id=c.instance_id AND si.master_id=sm.id AND si.source_id='r2-local' AND si.source_type='original' AND si.missing=0 AND si.tag_scanned=1 AND lower(si.suffix)='wav' AND si.storage_object_id=c.object_id JOIN storage_entries se ON se.id=c.entry_id AND se.instance_id=si.id AND se.kind='file' AND se.source_id='r2-local' AND se.parent_id='se-d8aa1e780c09470db7075f0130c65e36' AND se.object_id=si.storage_object_id JOIN storage_objects so ON so.id=c.object_id WHERE (SELECT COUNT(*) FROM storage_entries f WHERE f.instance_id=si.id AND f.kind='file')=1)=10 AND NOT EXISTS (SELECT 1 FROM albums WHERE id='al-f79d077d5e583272b3cc93b078334fe1') AND NOT EXISTS (SELECT 1 FROM song_masters WHERE id IN ('sm-04afa76593a947bab6e7aa9ab1fac848','sm-a04802ee79434c569c4a8037334fffe9','sm-aea8f18fd18a48d29d2a9b8e6c9cbfdc','sm-upload-0223d040-b1c','sm-upload-04789844-9c6','sm-upload-096c103b-c28','sm-upload-139421cf-b09','sm-upload-3ccc4425-662','sm-upload-5028ec56-8ea','sm-upload-558f35c9-d77') GROUP BY lower(trim(title)) HAVING COUNT(*)>1) AND NOT EXISTS (SELECT 1 FROM song_masters WHERE id IN ('sm-04afa76593a947bab6e7aa9ab1fac848','sm-a04802ee79434c569c4a8037334fffe9','sm-aea8f18fd18a48d29d2a9b8e6c9cbfdc','sm-upload-0223d040-b1c','sm-upload-04789844-9c6','sm-upload-096c103b-c28','sm-upload-139421cf-b09','sm-upload-3ccc4425-662','sm-upload-5028ec56-8ea','sm-upload-558f35c9-d77') AND track IS NOT NULL GROUP BY COALESCE(disc,0),track HAVING COUNT(*)>1) AND (SELECT COUNT(*) FROM storage_entries se JOIN song_instances si ON si.id=se.instance_id AND si.source_id='r2-local' AND lower(si.suffix)='wav' JOIN song_masters sm ON sm.id=si.master_id WHERE se.kind='file' AND se.source_id='r2-local' AND se.parent_id='se-d8aa1e780c09470db7075f0130c65e36' AND sm.album_id!='pending-uploads')=0 AND (SELECT COUNT(*) FROM storage_entries se JOIN song_instances si ON si.id=se.instance_id AND si.source_id='r2-local' AND lower(si.suffix)='wav' JOIN song_masters sm ON sm.id=si.master_id WHERE se.kind='file' AND se.source_id='r2-local' AND se.parent_id='se-d8aa1e780c09470db7075f0130c65e36' AND sm.album_id!='pending-uploads' AND sm.id NOT IN (''))=0 AND (SELECT COUNT(*) FROM song_masters sm JOIN song_instances si ON si.master_id=sm.id JOIN storage_entries se ON se.instance_id=si.id AND se.kind='file' WHERE sm.id IN ('') AND sm.album_id IN ('') AND se.source_id='r2-local' AND se.parent_id='se-d8aa1e780c09470db7075f0130c65e36' AND lower(si.suffix)='wav')=0);
